"""The managed library on disk: where each asset's .blend lives and the catalog definition file.

Paths and catalog ids are pure functions of the detection result: a rebuild produces the
same files with the same catalog UUIDs, so Blender keeps the user's view. Blender-side registration and
refresh live in realindex/blender_lib.py. Pure Python."""

import os

from . import names

CATS_FILE = "blender_assets.cats.txt"
CATS_HEADER = ("# This is an Asset Catalog Definition file for Blender.\n"
               "#\n"
               "# Generated by RealIndex from the folder structure of the drop root; edits are overwritten.\n"
               "# Empty lines and lines starting with `#` will be ignored.\n"
               "# The first non-ignored line should be the version indicator.\n"
               "# Other lines are of the format \"UUID:catalog/path/for/assets:simple catalog name\"\n\n"
               "VERSION 1\n\n")


def library_dir(state):
    return os.path.join(state, "library")


def catalog_paths(catalogs):
    """Every catalog path plus all of its parents, sorted."""
    out = set()
    for c in catalogs:
        parts = [p for p in (c or "").split("/") if p]
        for i in range(1, len(parts) + 1):
            out.add("/".join(parts[:i]))
    return sorted(out)


def cats_text(catalogs):
    lines = [CATS_HEADER]
    for path in catalog_paths(catalogs):
        lines.append("%s:%s:%s\n" % (names.catalog_id(path), path, names.catalog_simple_name(path)))
    return "".join(lines)


def write_cats(state, catalogs):
    """Write the catalog file when its content changes. Returns True when written."""
    path = os.path.join(library_dir(state), CATS_FILE)
    text = cats_text(catalogs)
    try:
        with open(path, "r", encoding="utf-8") as fh:
            if fh.read() == text:
                return False
    except OSError:
        pass
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8", newline="\n") as fh:
        fh.write(text)
    os.replace(tmp, path)
    return True


def read_cats(state):
    """{uuid: path} from the managed catalog file."""
    out = {}
    try:
        with open(os.path.join(library_dir(state), CATS_FILE), encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if not line or line.startswith("#") or line.startswith("VERSION"):
                    continue
                parts = line.split(":")
                if len(parts) >= 2:
                    out[parts[0]] = parts[1]
    except OSError:
        pass
    return out


def assign_paths(items):
    """items: [(key, catalog, name)] sorted by key -> {key: relpath under library/}.

    One .blend per asset at <catalog>/<safe name>.blend; a name clash in a catalog gets a short suffix
    derived from the asset's key, so the result never depends on processing order.
    """
    taken = {}
    out = {}
    for key, catalog, name in sorted(items):
        parts = [names.safe_filename(p, 40) for p in (catalog or "Unsorted").split("/") if p]
        folder = "/".join(parts)
        if len(folder) > 80:  # keep managed paths short (Windows limits); the catalog itself stays complete
            folder = "%s/%s" % (parts[0], names.short_hash(catalog, 10))
        base = names.safe_filename(name, 60)
        rel = "%s/%s.blend" % (folder, base)
        if rel.lower() in taken:
            rel = "%s/%s_%s.blend" % (folder, base, names.short_hash(key))
        taken[rel.lower()] = key
        out[key] = rel
    return out
